//! The line every generated file opens with: who wrote it, from what, and
//! how to write it again.

/// A generated file's header.
pub struct Header<'a> {
    /// The generator (`yog-ids`).
    pub tool: &'a str,
    /// What it generates from (`Yog-Mod-Loader/rust/crates/yog-ids`).
    pub source: &'a str,
    /// The command that regenerates it.
    pub regenerate: &'a str,
}

impl Header<'_> {
    /// The header's text, without a comment marker.
    pub fn text(&self) -> String {
        format!(
            "Generated by {} from {} — don't edit; regenerate with `{}`.",
            self.tool, self.source, self.regenerate
        )
    }

    /// The header as a `//` line comment (Rust, Java, TypeScript).
    pub fn line_comment(&self) -> String {
        format!("// {}\n", self.text())
    }
}
